package com.example.engine

import com.example.BuildConfig
import com.example.data.model.EventType
import com.example.data.model.Match
import com.example.data.model.MatchStatus
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import org.json.JSONArray
import org.json.JSONObject
import java.util.concurrent.TimeUnit

/**
 * Pre-match AI insight generated by analyzing hypothetical match data,
 * Poisson distribution, xG differentials, and tactical matchups.
 */
data class PreMatchAiInsight(
  val matchId: String,
  val summaryText: String,
  val recommendedPick: String,
  val recommendedOdd: Double,
  val confidenceScore: Int,
  val tacticalRiskAlert: String,
  val formComparison: String,
  val expectedScore: String,
  val keyFactors: List<String>
)

/**
 * Form prediction insight based on historical team data, head-to-head records,
 * and current league momentum.
 */
data class AutomatedFormPrediction(
  val matchId: String,
  val homeFormAnalysis: String,
  val awayFormAnalysis: String,
  val h2hSummary: String,
  val algorithmicVerdict: String,
  val valueRating: String, // "Yüksek Değer", "Banko", "Dengeli"
  val confidence: Int
)

/**
 * Intelligent Gemini AI Assistant & Deep Match Reasoning service.
 * Connects directly to Google's Gemini API via REST and provides fallback local deep analytical intelligence.
 */
object GeminiAnalysisService {

  private const val MODEL_NAME = "gemini-3.5-flash"
  private const val BASE_URL = "https://generativelanguage.googleapis.com/v1beta/models"

  private val client = OkHttpClient.Builder()
    .connectTimeout(60, TimeUnit.SECONDS)
    .readTimeout(60, TimeUnit.SECONDS)
    .writeTimeout(60, TimeUnit.SECONDS)
    .build()

  /**
   * Generates a deep strategic analysis and tactical breakdown for a match using Gemini AI.
   */
  suspend fun generateDeepMatchAnalysis(match: Match): String = withContext(Dispatchers.IO) {
    val apiKey = BuildConfig.GEMINI_API_KEY
    if (apiKey.isBlank() || apiKey == "MY_GEMINI_API_KEY") {
      return@withContext generateHeuristicAnalysis(match)
    }

    try {
      val prompt = """
        Sen profesyonel bir spor veri analisti ve yapay zeka futbol uzmanısın.
        Aşağıdaki canlı/bülten maç için Türkçe, son derece akıcı, profesyonel ve veriye dayalı 3-4 maddelik taktiksel bir özet oluştur:
        
        Lig: ${match.league}
        Karşılaşma: ${match.homeTeam} vs ${match.awayTeam}
        Durum / Skor: ${match.homeScore} - ${match.awayScore} (Dakika: ${match.minute}')
        xG İstatistikleri: Ev: ${match.statistics.xgHome} - Dep: ${match.statistics.xgAway}
        Topa Sahip Olma: %${match.statistics.possessionHome} - %${match.statistics.possessionAway}
        Şut / İsabet: ${match.statistics.shotsHome}(${match.statistics.shotsOnTargetHome}) vs ${match.statistics.shotsAway}(${match.statistics.shotsOnTargetAway})
        Yapay Zeka Poisson Olasılıkları: Ev: %${match.aiPrediction.homeWinProb}, Beraberlik: %${match.aiPrediction.drawProb}, Deplasman: %${match.aiPrediction.awayWinProb}
        
        Kullanıcıya kupon yaparken dikkat etmesi gereken kritik risk faktörünü, beklenen gol trendini ve oyun ritmini açıkla.
      """.trimIndent()

      val jsonBody = JSONObject().apply {
        val contentsArray = JSONArray().apply {
          val contentObj = JSONObject().apply {
            val partsArray = JSONArray().apply {
              val partObj = JSONObject().apply {
                put("text", prompt)
              }
              put(partObj)
            }
            put("parts", partsArray)
          }
          put(contentObj)
        }
        put("contents", contentsArray)
      }

      val request = Request.Builder()
        .url("$BASE_URL/$MODEL_NAME:generateContent?key=$apiKey")
        .post(jsonBody.toString().toRequestBody("application/json".toMediaType()))
        .build()

      val response = client.newCall(request).execute()
      if (!response.isSuccessful) {
        return@withContext generateHeuristicAnalysis(match)
      }

      val responseString = response.body?.string() ?: ""
      val rootJson = JSONObject(responseString)
      val candidates = rootJson.optJSONArray("candidates")
      val firstCandidate = candidates?.optJSONObject(0)
      val content = firstCandidate?.optJSONObject("content")
      val parts = content?.optJSONArray("parts")
      val text = parts?.optJSONObject(0)?.optString("text")

      if (!text.isNullOrBlank()) {
        text.trim()
      } else {
        generateHeuristicAnalysis(match)
      }
    } catch (_: Exception) {
      generateHeuristicAnalysis(match)
    }
  }

